effect.body:
//CarCharger laden bis voll, danach PV ins Grid schicken
charge_energy_box = Math.min(CarLoad_cycle, Avail_Pwr_cycle); 
TotalDemand -= charge_energy_box;
if (Overload) {Trace("-- Overload xx at: "+ sim.cycle)}
Trace("-- idle xx at: "+sim.cycle+" charge from Grid to box: "+charge_energy_box);
charge_energy_box=0; //reset just to be sure

if (TotalDemand <=0 ) {CarLoad=0;}
CarLoad_cycle = CarLoad * cycle_h;
NetDm=CarLoad-sim.PV;
Avail_Pwr_cycle = (GridLm + sim.PV )*cycle_h;
Battery_full=SOC > max_soc;
Battery_low = (SOC <= min_soc);
Overload=NetDm >= GridLm;
Grid_pwr_to_wallbox =0;
bat_pwr_to_wallbox=0; 
sim.cycle++;
Trace("—Cycle: "+sim.cycle+", NetDm: "+NetDm+"  SOC:"+SOC+" TotalDm: "+TotalDemand);

TotalDemand -= CarLoad_cycle; //Grid for box
available_grid_for_Battery= Avail_Pwr_cycle - CarLoad_cycle; //first load box then with delta the battery
charge_energy = Math.min(max_ch,available_grid_for_Battery);
if (charge_energy > 0) {
SOC += (charge_energy * Battery.efficiency);}  //sim.bat_max;

Trace("-- Charge xx SOC: "+ SOC +" Charge Energy: "+charge_energy);

if (CarLoad_cycle > Grid_pwr_to_wallbox) {
  bat_pwr_to_wallbox = Math.min(CarLoad_cycle- Grid_pwr_to_wallbox, bat_max_to_box); 
  SOC -= bat_pwr_to_wallbox;
  TotalDemand -= bat_pwr_to_wallbox; 
}
Trace("-- discharge Bat to Box at cycle: "+sim.cycle+"  TotalDemand: "+ TotalDemand);

Chargers = {};

Chargers["KebaP30"] = {Name: "KebaP30", max_power: 11,demand:40};
Chargers["SieChargeD"] = {Name: "SieChargeD", max_power: 22,demand:60};
Chargers["SieCPC20"] = {Name: "SieCPC20", max_power: 22,demand:50};

if (CarLoad_cycle > bat_pwr_to_wallbox) {
  	Grid_pwr_to_wallbox = Math.min((CarLoad_cycle -   bat_pwr_to_wallbox), Avail_Pwr_cycle); 
  	// load up to Avail_Pwr_cycle which is (GridLm + sim.PV )*cycle_h
   	TotalDemand -= Grid_pwr_to_wallbox; 
}
Trace("—load Grid to box  at cycle: "+sim.cycle+"  TotalDemand: "+ TotalDemand);

//mindestens 1 kw bei Wolken
sim.minPV=1;
sim.steps = Math.floor((PV1 -sim. minPV) / 0.1) + 1;
rnd = Math.floor(Math.random() * sim.steps);
sim.PV = sim.minPV + rnd * 0.1;
PVCons=(sim.PV * cycle_h);

