@ENDVALU;@PRMT=@ENDPRMT;@ENDPROP;$DES;$CLT={5A7B75FF-FED5-45d7-BA39-B86994AB5CA3}$CLT;$ENDXREF;

$XREFPROP=$XID={5C0C9128-E0B2-435b-90B2-6518A8EC73DA}$XID;$NAM=CustomProperties$NAM;$TYP=element property$TYP;$VIS=Public$VIS;$PAR=0$PAR;$DES=@PROP=@NAME=effect@ENDNAME;@TYPE=String@ENDTYPE;@VALU=if (CarLoad_cycle > bat_pwr_to_wallbox) {
  	Grid_pwr_to_wallbox = Math.min((CarLoad_cycle -   bat_pwr_to_wallbox), Avail_Pwr_cycle); 
  	// load up to Avail_Pwr_cycle which is (GridLm + sim.PV )*cycle_h
   	TotalDemand -= Grid_pwr_to_wallbox; 
}
Trace("—load Grid to box  at cycle: "+sim.cycle+"  TotalDemand: "+ TotalDemand);
@ENDVALU;@PRMT=@ENDPRMT;@ENDPROP;$DES;$CLT={852E632F-3ADF-4e6d-8084-C67E1F078A63}$CLT;$SUP=<none>$SUP;$ENDXREF;

$XREFPROP=$XID={3DB2F43D-024B-4cd1-AFE6-92ECECA3EB32}$XID;$NAM=CustomProperties$NAM;$TYP=element property$TYP;$VIS=Public$VIS;$PAR=0$PAR;$DES=@PROP=@NAME=effect@ENDNAME;@TYPE=String@ENDTYPE;@VALU=//mindestens 1 kw bei Wolken
sim.minPV=1;
sim.steps = Math.floor((PV1 -sim. minPV) / 0.1) + 1;
rnd = Math.floor(Math.random() * sim.steps);
sim.PV = sim.minPV + rnd * 0.1;
PVCons=(sim.PV * cycle_h);

@ENDVALU;@PRMT=@ENDPRMT;@ENDPROP;$DES;$CLT={8000803F-F15B-49b4-A8FE-48FA5FEC8CBE}$CLT;$SUP=<none>$SUP;$ENDXREF;

