@ENDVALU;@PRMT=@ENDPRMT;@ENDPROP;$DES;$CLT={9D6FF2DC-1137-4d61-8D84-4AB24B7482C9}$CLT;$SUP=<none>$SUP;$ENDXREF;

$XREFPROP=$XID={D96CCCC5-5766-43c7-B969-A959A2D9AA72}$XID;$NAM=CustomProperties$NAM;$TYP=element property$TYP;$VIS=Public$VIS;$PAR=0$PAR;$DES=@PROP=@NAME=effect@ENDNAME;@TYPE=String@ENDTYPE;@VALU=bat_pwr_to_wallbox=0;
max_ch = Battery.max_charge/1000*cycle_h;
max_dis = Battery.max_discharge/1000*cycle_h;
bat_max_to_box = max_dis*Battery.efficiency; 
sim.bat_max=Battery.max_Cap/1000;
SOC=Battery.init_SOC/1000;
max_soc=sim.bat_max*0.9; //90 Percent
mid_soc=sim.bat_max*0.7;
min_soc=sim.bat_max*0.1;
Trace("--Battery Capacity "+sim.bat_max);
sim.cycle=0;
@ENDVALU;@PRMT=@ENDPRMT;@ENDPROP;$DES;$CLT={09B9722F-1F2B-4f83-9959-C2776DEDA6F1}$CLT;$SUP=<none>$SUP;$ENDXREF;

